// Normaliza os dados que a IA mandou, de forma defensiva.
const inp   = (() => {
  const t = (() => { try { return $('Recebe da IA (Renovação)').first().json; } catch(e){ return null; } })();
  if (t && t.bid_id !== undefined) return t;           // veio do trigger (produção OU pin no trigger)
  const i = (() => { try { return $input.first().json; } catch(e){ return null; } })();
  if (i && i.bid_id !== undefined) return i;            // veio direto no nó (pin no Normaliza)
  return t || i || {};                                  // último recurso
})();
const cfg   = $('Configuracao').first().json;

// --- token: aceita com ou sem "Bearer", sempre devolve limpo e com "Bearer " uma vez
const rawToken = (inp.token || '').toString().trim();
const tokenLimpo = rawToken.replace(/^Bearer\s*/i, '').trim();      // sem prefixo
const authHeader = tokenLimpo ? ('Bearer ' + tokenLimpo) : '';      // com 1 prefixo

// O token e preenchido pelo MODELO e ja chegou vazio em producao. Sem esta guarda,
// authHeader vazio faz a API responder 403 e o fluxo traduz isso como
// "anuncio nao encontrado" -- mentira ao cliente. Declara explicitamente.
// Tambem recusa placeholder, que o modelo ja tentou mandar.
const ehPlaceholder = /^(<?token>?|<?bearer>?|bearer\s*<.*>|null|undefined|string)$/i.test(tokenLimpo);
const token_ok = tokenLimpo.length >= 20 && !ehPlaceholder;

// --- bid_id obrigatório e numérico
const bidId = Number(inp.bid_id);
const bidValido = Number.isInteger(bidId) && bidId > 0;

// --- validade: default 30; só aceita 7/15/30
let validade = Number(inp.validade);
if (![7, 15, 30].includes(validade)) validade = 30;

return [{
  json: {
    base_url:   cfg.base_url,
    authKey:    cfg.authKey,
    bid_id:     bidId,
    bid_valido: bidValido,
    token_limpo: tokenLimpo,
    token_ok:   token_ok,
    entrada_ok: bidValido && token_ok,
    auth_header: authHeader,
    validade:   validade,
    period_hour: validade * 24,          // ex.: 720 para 30 dias
    email:      (inp.email || '').toString().trim(),
    // O endpoint de login NAO normaliza nada: aceita so DDD+numero, sem o 55
    // (11969433278 loga; 5511969433278 responde PHONE_NOT_FOUND). Medido 06/10/2026.
    phone_login: (() => {
      const d = (inp.phone_number || '').toString().replace(/\D/g, '').replace(/^0+/, '');
      return d.replace(/^55(?=\d{10,11}$)/, '');
    })(),
    phone_number: (() => {
      // A guarda de dono NAO pode depender do formato que o modelo mandou.
      // Normaliza para e164 brasileiro: 55 + DDD + numero (com o 9 quando faltar).
      const d = (inp.phone_number || '').toString().replace(/\D/g, '');
      if (!d) return '';
      if (d.length === 13 && d.startsWith('55')) return d;            // 55 + DDD + 9 digitos
      if (d.length === 12 && d.startsWith('55')) {                     // 55 + DDD + 8 digitos -> insere o 9
        return '55' + d.slice(2, 4) + '9' + d.slice(4);
      }
      if (d.length === 11) return '55' + d;                            // DDD + 9 digitos
      if (d.length === 10) return '55' + d.slice(0, 2) + '9' + d.slice(2); // DDD + 8 digitos
      return d;                                                        // formato desconhecido: passa cru e a query decide
    })(),
  }
}];

// Clona o anúncio original: reaproveita TODOS os objetos, troca só a duração.
// Mapeamento confirmado contra o retorno real de GET /public/resources/bid/{id}.
const raw  = $('Busca Anúncio Original').first().json;
const semEnv = (raw && typeof raw === 'object' && 'statusCode' in raw) ? raw.body : raw;
