const duration = norm.period_hour + ":00";

// validação mínima: sem produto/quantidade não dá pra recriar fiel
const faltando = [];
if (orig.product == null)  faltando.push('produto');
if (orig.quantity == null) faltando.push('quantidade');

const payload = {
  marketId:          val(orig.marketId, 1),
  operationId:       val(orig.operationId, 2),      // 1=compra 2=venda
  typeId:            val(orig.typeId, 2),
  product:           orig.product,                  // objeto completo
  visibilityId:      val(orig.visibilityId, 2),
  currencyId:        val(orig.currencyId, 1),
  price:             val(orig.price, 0),
  priceUnit:         orig.priceUnit,                // objeto completo
  quantity:          orig.quantity,
  quantityUnit:      orig.quantityUnit,             // objeto completo
  pickUp:            orig.pickUp,                   // objeto completo (cidade+estado)
  pickUpDescription: val(orig.pickUpDescription, null),
  logistics:         orig.logistics,               // objeto completo
  note:              val(orig.note, null),
  urlYouTube:        val(orig.urlYouTube, null),
  areaId:            val(orig.areaId, 1),
  duration:          duration,
  files:             []
};

